import { h } from 'vue';
import App from '../App.vue';
import View from '../components/GeneratedViewPage.vue';
import Home from '../components/home/HomePage.vue';
import HomeAsk from '../components/home/HomeAsk.vue';
import Palette from '../components/SearchPalette.vue';
import EmbeddingMap from '../components/EmbeddingMap.vue';
import snapshot from '../data/archiveDemoView.json';
import searchItems from '../data/archiveDemoSearch.json';

// Keep the production render functions, scoped styles and responsive rules.
// Preview components replace service/lifecycle work with a supplied clock.
// This module is loaded only by the isolated, non-interactive preview document.
function presentation(component, options) {
  const result = { ...component };
  for (const key of ['mixins', 'extends', 'watch', 'created', 'mounted', 'beforeMount', 'beforeUnmount', 'unmounted', 'beforeRouteLeave', 'beforeRouteUpdate']) delete result[key];
  return { ...result, inject: ['previewClock'], ...options,
    computed: { ...component.computed, ...options.computed },
    methods: { ...component.methods, ...options.methods },
  };
}

const question = snapshot.view.question;
const answerBody = snapshot.view.sections[0].blocks[0].text;
const answer = `${answerBody} [1]`;
const sources = [snapshot.sources[0]].map((source, index) => ({ ...source, id: index + 1 }));
const offer = { title: snapshot.view.title, description: 'Explore the places, memories and original writing.' };
const empty = { render: () => h('div') };
const PreviewMap = {
  ...EmbeddingMap, inject: ['previewClock'],
  watch: { ...EmbeddingMap.watch, 'previewClock.state'() { this.syncPreviewProjection(); } },
  methods: { ...EmbeddingMap.methods,
    start3dMotion() { this.syncPreviewProjection(); },
    syncPreviewProjection() {
      if (this.viewMode !== '3d' || !this._points?.length || !this._w) return;
      this._yaw = -.72 + this.previewClock.state.time * .00016;
      this.updateProjection(); this.draw();
    },
  },
};

const homeAnswerOpen = clock => ['home', 'access-home'].includes(clock.scene) && ['thinking', 'answer', 'composing'].includes(clock.state.phase);

export const PreviewHomeAsk = presentation(HomeAsk, {
  name: 'ArchivePreviewHomeAsk',
  data() {
    // A presentation never restores or writes the visitor's real Ask session.
    return { open: false, question: '', submitted: '', answer: '', sources,
      busy: false, error: '', turn: 0, composing: false, routing: 'offer',
      grounded: [], viewError: '', session: null };
  },
  computed: {
    locked() { return this.busy || this.viewBusy; },
    citations() { return this.answer ? sources : []; },
    followUps() { return []; },
    offer() { return offer; },
    existingView() { return false; },
    viewBusy() { return this.previewClock.state.phase === 'composing'; },
    viewStart() { return this.previewClock.composeStartedAt; },
    actions() { return []; },
  },
  watch: {
    'previewClock.state': { immediate: true, handler(state) {
      this.open = homeAnswerOpen(this.previewClock);
      this.busy = state.phase === 'thinking' || (state.phase === 'answer' && state.answerProgress < 1);
      this.question = this.open ? '' : (state.typed || '');
      this.submitted = this.open ? question : '';
      // Reuse the real Ask rendering as text arrives. Completing the stream
      // reveals its citation and controls, just as the live response does.
      const progress = state.answerProgress || 0;
      this.answer = !this.open ? '' : progress >= 1 ? answer
        : answerBody.slice(0, Math.floor(answerBody.length * progress));
    } },
  },
});

export const PreviewHome = presentation(Home, {
  name: 'ArchivePreviewHome',
  components: { ...Home.components, HomeAsk: PreviewHomeAsk,
    HomeContact: empty, CoastDevelopment: empty, GalleryBuildingMark: empty },
  data() { return { ...Home.data.call(this), reduced: false }; },
  watch: {
    'previewClock.dark'(dark) { this.dark = dark; },
    'previewClock.state': { immediate: true, handler() {
      this.askOpen = homeAnswerOpen(this.previewClock);
      this.width = this.previewClock.viewportWidth;
      this.height = this.previewClock.viewportHeight;
    } },
  },
});

export const PreviewPalette = presentation(Palette, {
  name: 'ArchivePreviewPalette',
  components: { ...Palette.components, EmbeddingMap: PreviewMap },
  data() {
    const data = Palette.data.call(this);
    return { ...data, loaded: true, viewOfferVisible: true, askSources: sources,
      recentSharedViews: [{ id: snapshot.id, title: snapshot.view.title, question }],
    };
  },
  computed: {
    askReady() { return true; },
    canReturnToView() { return false; },
    viewOffer() { return offer; },
    askFollowUpQuestions() { return []; },
    results() { return this.mode === 'search' ? searchItems : []; },
  },
  watch: {
    'previewClock.state': { immediate: true, handler(state) {
      this.open = ['palette', 'access-header', 'access-sidebar'].includes(this.previewClock.scene) && state.open;
      this.mode = state.mode || 'search';
      this.query = this.mode === 'search' ? 'Shanghai' : this.mode === 'ask' ? question : '';
      this.askAnswer = answer;
      this.mobileModeMenuOpen = state.modeMenu;
    } },
  },
  mounted() { this._spAnims = new Set(); },
  beforeUnmount() { this._spAnims?.forEach(animation => animation.stop()); },
});

export const PreviewView = presentation(View, {
  name: 'ArchivePreviewView',
  data() {
    return { ...View.data.call(this), view: snapshot.view,
      sourcesById: new Map(snapshot.sources.map(source => [source.source_id, source])),
      currentSourcesById: new Map(snapshot.sources.map(source => [source.source_id, source])),
      sourcesLoading: false, shareId: snapshot.id, shareVisibility: 'public',
    };
  },
  mounted() {
    // The saved snapshot bypasses the normal loading flow that publishes this title.
    this.updatePageTitle();
    this.$watch(() => this.exhibitionOpen && this.$refs.exhibition?.ready, ready => {
      this.previewClock.exhibitionReady = Boolean(ready);
      if (ready) this.$nextTick(() => {
        this.syncPreviewVisit();
        window.parent.postMessage({ type: 'archive-preview-scene-ready', scene: this.previewClock.scene }, location.origin);
      });
    }, { flush: 'post' });
    this.prepareExhibition();
    this.syncPreviewExhibition();
  },
  beforeUnmount() { this._previewClosed = true; this.previewClock.exhibitionReady = false; },
  watch: {
    'previewClock.exhibition'() { this.syncPreviewExhibition(); },
    'previewClock.state'() { this.syncPreviewVisit(); },
    'previewClock.playing'() { this.syncPreviewVisit(); },
  },
  methods: {
    syncPreviewVisit() {
      const exhibition = this.$refs.exhibition;
      if (!exhibition?.ready) return;
      exhibition._scene?.setPaused(!this.previewClock.playing);
      const time=this.previewClock.state.time;
      const target = this.previewClock.state.visitStep ?? (this.previewClock.scene === 'exhibition' ? Math.floor((time - 4200)/5500) : -1);
      const step = Math.min(exhibition.exhibition.steps.length - 1, target);
      const restarted = time < (this._previewVisitTime || 0);
      this._previewVisitTime = time;
      if (exhibition.visitStepIndex !== step || restarted) exhibition.goStep(step, restarted || !this.previewClock.playing);
    },
    async syncPreviewExhibition() {
      if (!this.previewClock.exhibition) { this.exhibitionOpen = false; this.museumArrival = false; this.previewClock.exhibitionReady = false; return; }
      this.museumArrival = true;
      await this.prepareExhibition();
      if (this._previewClosed || !this.previewClock.exhibition) return;
      this.exhibitionPosition = null;
      this.exhibitionOpen = Boolean(this.ExhibitionComponent);
    },
  },
  computed: {
    showBackLink() { return true; },
    originLabel() { return 'Home'; },
    embedded() { return false; },
  },
});

export const PreviewApp = presentation(App, {
  name: 'ArchivePreviewApp',
  components: { ...App.components, SearchPalette: PreviewPalette },
  data() {
    return { ...App.data.call(this), homeArrivalPending: false, initialChromeReady: true };
  },
  computed: {
    showScrollProgress() { return false; },
    // The recorded exhibition uses a non-modal dialog. Hide site chrome here
    // just as the production modal covers it during a real visit.
    previewMode() { return (this.previewClock.exhibition && this.previewClock.exhibitionReady) || this.previewClock.state.phase === 'gallery'; },
  },
  methods: {
    // The memory router belongs to the presentation clock, with no history,
    // saved positions, analytics, global shortcuts or visitor state.
    beforeRouteEnter() {}, finishRouteProgressTransition() {},
  },
});
