// Shared helpers for landing on a section after navigation. The slug scheme
// must stay in sync with scripts/build-search-index.mjs and the in-page
// assignAnchors() helpers in SearchPalette.vue / IndexPage.vue.
export function slugify(s) {
  return String(s)
    .replace(/<[^>]+>/g, '')
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 80);
}

// Assign slug ids to the current page's headings / timeline titles, mirroring
// the build-time extractor, so a source link can deep-link to its section.
export function assignAnchors(root) {
  if (!root) return;
  const useEntries = !!root.querySelector('li.title');
  const els = useEntries ? root.querySelectorAll('li.title') : root.querySelectorAll('h2, h3');
  const seen = new Set();
  els.forEach((el) => {
    const base = slugify(el.getAttribute('data-source-anchor') || el.textContent);
    if (!base) return;
    let slug = base;
    let n = 2;
    while (seen.has(slug)) slug = `${base}-${n++}`;
    seen.add(slug);
    el.id = slug;
  });
}

// Land on the entry's visual top, not the title: research/projects keep the
// date label at the top (.timeline-event); education/experience keep the
// school/company block top (the entry <section>).
export function scrollTargetFor(el) {
  const te = el.closest('.timeline-event');
  if (te) return te;
  if (el.matches && el.matches('li.title')) {
    const sec = el.closest('section');
    if (sec) return sec;
  }
  return el;
}

// A citation may point into an implementation disclosure. Open only the
// containing panels through their own controls, preserving Vue's state.
function containingDisclosureControls(el) {
  const controls = [];
  let node = el;
  while (node && node !== document.body) {
    if (node.matches?.('.impl-details-panel')) {
      const control = node.closest('.impl-details')?.querySelector('.impl-details-toggle');
      if (control?.getAttribute('aria-controls') === node.id
        && control.getAttribute('aria-expanded') === 'false') controls.push(control);
    }
    node = node.parentElement;
  }
  return controls.reverse();
}

// Reveal animations start entries translated down 16-20px; the transform
// resolves when the entry enters the viewport. scrollIntoView aims at the
// transformed box and lands short once the transform settles, so read the
// settled layout position instead.
function revealTranslateY(el) {
  let total = 0;
  let node = el;
  while (node && node !== document.body) {
    const tr = getComputedStyle(node).transform;
    if (tr && tr !== 'none') {
      const m2 = tr.match(/^matrix\(([^)]+)\)$/);
      if (m2) {
        const parts = m2[1].split(',').map(parseFloat);
        if (parts.length >= 6) total += parts[5];
      } else {
        const m3 = tr.match(/^matrix3d\(([^)]+)\)$/);
        if (m3) {
          const parts = m3[1].split(',').map(parseFloat);
          if (parts.length >= 16) total += parts[13];
        }
      }
    }
    node = node.parentElement;
  }
  return total;
}

// The document position of the element with every reveal transform (translate
// AND scale) neutralised, i.e. where it will sit once the reveal settles.
function settledDocumentTop(el) {
  const changed = [];
  let node = el;
  while (node && node !== document.body) {
    const tr = getComputedStyle(node).transform;
    if (tr && tr !== 'none' && tr !== 'matrix(1, 0, 0, 1, 0, 0)') {
      changed.push([node, node.style.getPropertyValue('transform'), node.style.getPropertyPriority('transform')]);
      node.style.transform = 'none';
    }
    node = node.parentElement;
  }
  const top = el.getBoundingClientRect().top + window.scrollY;
  changed.forEach(([n, value, priority]) => {
    if (value) n.style.setProperty('transform', value, priority);
    else n.style.removeProperty('transform');
  });
  return top;
}

export function landingOffset(target) {
  const authoredMargin = parseFloat(getComputedStyle(target).scrollMarginTop) || 0;
  let chapterBottom = 0;
  const overlayBottom = ['.header', '.chapter-rail:not(.rail-static)', '.case-navigation']
    .map((selector) => document.querySelector(selector))
    .filter(Boolean)
    .reduce((bottom, element) => {
      const style = getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      const overlaysPage = (style.position === 'fixed' || style.position === 'sticky')
        && style.display !== 'none'
        && style.visibility !== 'hidden'
        && rect.bottom > 0;
      if (!overlaysPage) return bottom;
      const occupiedBottom = style.position === 'sticky'
        ? (parseFloat(style.top) || 0) + rect.height
        : rect.bottom;
      if (element.matches('.case-navigation')) chapterBottom = occupiedBottom;
      const clearance = parseFloat(style.getPropertyValue('--anchor-clearance')) || 0;
      return Math.max(bottom, occupiedBottom + clearance);
    }, 0);

  // The return control moves below the chapter bar. Reserve its final position
  // when it overlaps the destination heading, even before the bar has pinned.
  const targetRect = target.getBoundingClientRect();
  const back = document.querySelector('.site-back-global, .view-return-slot');
  let returnBottom = 0;
  // Collection entries align under the site header. The floating return cue
  // is not a full-width toolbar and must not add another row to their offset.
  const collectionTarget = target.matches?.('.collection-card, .collection-index-unit, .timeline-event');
  if (back && !collectionTarget) {
    const style = getComputedStyle(back);
    const rect = back.getBoundingClientRect();
    if (style.position === 'fixed' && style.display !== 'none'
      && rect.right > targetRect.left && rect.left < targetRect.right) {
      returnBottom = Math.max(parseFloat(style.top) || 0, chapterBottom ? chapterBottom + 8 : 0) + rect.height;
    }
  }
  if (!overlayBottom && !returnBottom) return authoredMargin;
  const breathingRoom = window.matchMedia?.('(max-width: 760px)').matches ? 12 : 16;
  return Math.max(authoredMargin, Math.ceil(Math.max(overlayBottom, returnBottom) - 0.01) + breathingRoom);
}

